1	package zkcircuit
2	
3	import (
4		"sort"
5		"strings"
6	)
7	
8	// This file holds the domain operations of the persistent workbench. Every
9	// mutating operation validates its request before touching state, runs under
10	// the shared process lock and either commits one complete new state or
11	// commits nothing.
12	
13	// CreateCircuit creates a draft circuit version identified by Name+Version.
14	//
15	// The name must be non-empty and not only whitespace; Version must be
16	// positive; Constraints must be positive; the input counts must not be
17	// negative. Creating an already-existing version is idempotent when the
18	// description is identical (the stored record is returned unchanged); a
19	// differing description is reported as ErrConflict. Nothing about an
20	// existing version — frozen or not — is ever replaced by Create.
21	func (s *Store) CreateCircuit(c Circuit) (Circuit, error) {
22		if err := validateCircuitKey(c.Name, c.Version); err != nil {
23			return Circuit{}, err
24		}
25		if err := validateCounts(c.Constraints, c.PublicInputs, c.PrivateInputs); err != nil {
26			return Circuit{}, err
27		}
28	
29		var result Circuit
30		err := s.withLock(func() (bool, error) {
31			if existing := findCircuit(s.data.Circuits, c.Name, c.Version); existing != nil {
32				if existing.Description != c.Description {
33					return false, conflictf("circuit %q version %d already exists with a different description", c.Name, c.Version)
34				}
35				result = circuitFromPersist(*existing)
36				return false, nil
37			}
38			record := persistCircuit{
39				Name: c.Name, Version: c.Version,
40				Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
41				Frozen: false, Description: c.Description,
42			}
43			s.data.Circuits = append(s.data.Circuits, record)
44			result = circuitFromPersist(record)
45			return true, nil
46		})
47		return result, err
48	}
49	
50	// UpdateCircuit modifies a draft circuit version. It must target an existing,
51	// unfrozen version explicitly: unknown versions yield ErrNotFound and frozen
52	// versions yield ErrFrozen. On success the counts and description are
53	// replaced as one atomic change; partial updates can never be observed.
54	func (s *Store) UpdateCircuit(c Circuit) (Circuit, error) {
55		if err := validateCircuitKey(c.Name, c.Version); err != nil {
56			return Circuit{}, err
57		}
58		if err := validateCounts(c.Constraints, c.PublicInputs, c.PrivateInputs); err != nil {
59			return Circuit{}, err
60		}
61	
62		var result Circuit
63		err := s.withLock(func() (bool, error) {
64			existing := findCircuit(s.data.Circuits, c.Name, c.Version)
65			if existing == nil {
66				return false, notFoundf("circuit %q version %d does not exist", c.Name, c.Version)
67			}
68			if existing.Frozen {
69				return false, frozenf("circuit %q version %d is frozen and its description cannot be modified", c.Name, c.Version)
70			}
71			// When a definition is already imported, changing the three counts is
72			// only accepted as a whole if the definition stays legal under them
73			// (exact constraint count, all wires inside the new input layout).
74			if existing.Definition != nil {
75				parsed, perr := definitionFromPersist(*existing.Definition, existing.PublicInputs, existing.PrivateInputs)
76				if perr != nil {
77					return false, corruptf("stored definition for %q v%d is unreadable: %v", c.Name, c.Version, perr)
78				}
79				if !parsed.compatibleWith(c.Constraints, c.PublicInputs, c.PrivateInputs) {
80					return false, invalidf("update rejected: it would make the imported constraint definition illegal (constraint count or wire layout mismatch); the whole change is refused")
81				}
82			}
83			existing.Constraints = c.Constraints
84			existing.PublicInputs = c.PublicInputs
85			existing.PrivateInputs = c.PrivateInputs
86			existing.Description = c.Description
87			result = circuitFromPersist(*existing)
88			return true, nil
89		})
90		return result, err
91	}
92	
93	// PartialCircuit carries optional replacement fields for one draft circuit
94	// version. A nil pointer leaves the stored field untouched; a non-nil pointer
95	// — even to zero or to the empty string — replaces the field. This lets a
96	// caller change exactly one field without restating the others.
97	type PartialCircuit struct {
98		Constraints   *int
99		PublicInputs  *int
100		PrivateInputs *int
101		Description   *string
102	}
103	
104	// UpdateCircuitPartial modifies selected fields of a draft circuit version.
105	//
106	// Only fields present in patch are changed; omitted fields keep their stored
107	// values. The whole merged result is validated before anything is committed:
108	// constraints must stay positive and input counts non-negative, and when a
109	// constraint definition is already imported the merged counts must keep it
110	// legal (exact constraint count, every referenced wire inside the new input
111	// layout). Any rejected field refuses the entire change — description,
112	// counts and the stored definition all remain as they were.
113	//
114	// Unknown versions yield ErrNotFound and frozen versions ErrFrozen even when
115	// no field is being changed. A patch that provides no modifiable field at
116	// all returns the stored record unchanged and commits nothing (no new
117	// version, no data write).
118	func (s *Store) UpdateCircuitPartial(name string, version int, patch PartialCircuit) (Circuit, error) {
119		if err := validateCircuitKey(name, version); err != nil {
120			return Circuit{}, err
121		}
122	
123		var result Circuit
124		err := s.withLock(func() (bool, error) {
125			existing := findCircuit(s.data.Circuits, name, version)
126			if existing == nil {
127				return false, notFoundf("circuit %q version %d does not exist", name, version)
128			}
129			if existing.Frozen {
130				return false, frozenf("circuit %q version %d is frozen and cannot be modified", name, version)
131			}
132			// Merge the provided fields over the stored record; omitted fields
133			// keep their committed values.
134			merged := *existing
135			if patch.Constraints != nil {
136				merged.Constraints = *patch.Constraints
137			}
138			if patch.PublicInputs != nil {
139				merged.PublicInputs = *patch.PublicInputs
140			}
141			if patch.PrivateInputs != nil {
142				merged.PrivateInputs = *patch.PrivateInputs
143			}
144			if patch.Description != nil {
145				merged.Description = *patch.Description
146			}
147			if err := validateCounts(merged.Constraints, merged.PublicInputs, merged.PrivateInputs); err != nil {
148				return false, err
149			}
150			// When a definition is already imported, the merged counts must keep
151			// it legal (exact constraint count, all wires inside the new input
152			// layout). The definition itself is never touched here.
153			if existing.Definition != nil {
154				parsed, perr := definitionFromPersist(*existing.Definition, existing.PublicInputs, existing.PrivateInputs)
155				if perr != nil {
156					return false, corruptf("stored definition for %q v%d is unreadable: %v", name, version, perr)
157				}
158				if !parsed.compatibleWith(merged.Constraints, merged.PublicInputs, merged.PrivateInputs) {
159					return false, invalidf("update rejected: it would make the imported constraint definition illegal (constraint count or wire layout mismatch); the whole change is refused")
160				}
161			}
162			// No modifiable field was provided: return the stored record without
163			// committing anything.
164			if patch.Constraints == nil && patch.PublicInputs == nil && patch.PrivateInputs == nil && patch.Description == nil {
165				result = circuitFromPersist(*existing)
166				return false, nil
167			}
168			existing.Constraints = merged.Constraints
169			existing.PublicInputs = merged.PublicInputs
170			existing.PrivateInputs = merged.PrivateInputs
171			existing.Description = merged.Description
172			result = circuitFromPersist(*existing)
173			return true, nil
174		})
175		return result, err
176	}
177	
178	// FreezeCircuit freezes a circuit version. Unknown versions yield
179	// ErrNotFound. Freezing an already-frozen version returns that version
180	// unchanged (idempotent). Once frozen, name, version and the three counts
181	// can never change again.
182	func (s *Store) FreezeCircuit(name string, version int) (Circuit, error) {
183		if err := validateCircuitKey(name, version); err != nil {
184			return Circuit{}, err
185		}
186	
187		var result Circuit
188		err := s.withLock(func() (bool, error) {
189			existing := findCircuit(s.data.Circuits, name, version)
190			if existing == nil {
191				return false, notFoundf("circuit %q version %d does not exist", name, version)
192			}
193			if existing.Frozen {
194				result = circuitFromPersist(*existing)
195				return false, nil
196			}
197			existing.Frozen = true
198			result = circuitFromPersist(*existing)
199			return true, nil
200		})
201		return result, err
202	}
203	
204	// CopyCircuit creates a new draft version of a circuit name by copying a
205	// frozen source version. The target version must be a positive integer
206	// different from the source version; it need not be consecutive or greater.
207	//
208	// The copy carries over the source's description, constraint count, public
209	// and private input counts, and — when the source has one — its complete
210	// constraint definition (modulus, constraint order and wire layout). A
211	// counts-only source produces a counts-only target with no definition. The
212	// new draft is fully independent: updating, re-importing or freezing it
213	// never touches the source, and the source's compiled artifacts, trusted
214	// setup and registered jobs are never copied or bound to the target. The
215	// target must register its own setup and compile its own artifact after
216	// freezing; the source's hash cannot satisfy the target's input checks or
217	// job bindings.
218	//
219	// Copying is idempotent: if the target already exists as a draft whose
220	// description, counts and definition are semantically equal to the source,
221	// the stored target is returned unchanged and nothing is written. A frozen
222	// target or a target whose description, counts or definition has changed
223	// yields ErrConflict. An unknown source yields ErrNotFound and an unfrozen
224	// source ErrNotFrozen; the source is always checked before the target.
225	func (s *Store) CopyCircuit(name string, version, toVersion int) (Circuit, error) {
226		if err := validateCircuitKey(name, version); err != nil {
227			return Circuit{}, err
228		}
229		if err := validateCircuitKey(name, toVersion); err != nil {
230			return Circuit{}, err
231		}
232		if version == toVersion {
233			return Circuit{}, invalidf("source and target version must differ for circuit %q", name)
234		}
235	
236		var result Circuit
237		err := s.withLock(func() (bool, error) {
238			source := findCircuit(s.data.Circuits, name, version)
239			if source == nil {
240				return false, notFoundf("circuit %q version %d does not exist", name, version)
241			}
242			if !source.Frozen {
243				return false, notFrozenf("circuit %q version %d must be frozen before it can be copied as a new draft", name, version)
244			}
245			target := findCircuit(s.data.Circuits, name, toVersion)
246			if target != nil {
247				if target.Frozen {
248					return false, conflictf("circuit %q version %d already exists and is frozen", name, toVersion)
249				}
250				if !circuitCopyMatches(*source, *target) {
251					return false, conflictf("circuit %q version %d already exists with content that differs from the source", name, toVersion)
252				}
253				result = circuitFromPersist(*target)
254				return false, nil
255			}
256			record := persistCircuit{
257				Name: name, Version: toVersion,
258				Constraints: source.Constraints, PublicInputs: source.PublicInputs, PrivateInputs: source.PrivateInputs,
259				Frozen: false, Description: source.Description,
260			}
261			if source.Definition != nil {
262				def := *source.Definition
263				record.Definition = &def
264			}
265			s.data.Circuits = append(s.data.Circuits, record)
266			result = circuitFromPersist(record)
267			return true, nil
268		})
269		return result, err
270	}
271	
272	// RecordSetup records a trusted setup for one frozen circuit version. The
273	// record belongs exclusively to that name+version. Unknown versions yield
274	// ErrNotFound; non-frozen versions yield ErrNotFrozen. Re-registering a
275	// setup for the same version is idempotent and adds no duplicate record.
276	func (s *Store) RecordSetup(name string, version int) (Setup, error) {
277		if err := validateCircuitKey(name, version); err != nil {
278			return Setup{}, err
279		}
280	
281		var result Setup
282		err := s.withLock(func() (bool, error) {
283			circuit := findCircuit(s.data.Circuits, name, version)
284			if circuit == nil {
285				return false, notFoundf("circuit %q version %d does not exist", name, version)
286			}
287			if !circuit.Frozen {
288				return false, notFrozenf("circuit %q version %d must be frozen before its trusted setup is recorded", name, version)
289			}
290			if existing := findSetup(s.data.Setups, name, version); existing != nil {
291				result = setupFromPersist(*existing)
292				return false, nil
293			}
294			record := persistSetup{Name: name, Version: version}
295			s.data.Setups = append(s.data.Setups, record)
296			result = setupFromPersist(record)
297			return true, nil
298		})
299		return result, err
300	}
301	
302	// SubmitJob accepts and stores a prove job. Only kind "prove" is accepted;
303	// no proving computation runs, the accepted request alone is persisted.
304	//
305	// The job id must be non-empty and not only whitespace, circuit name and
306	// version must be explicit and Attempt must be positive. Failure reasons are
307	// distinguishable: ErrNotFound (version unknown), ErrNotFrozen (version is
308	// still a draft) and ErrSetupMissing (no trusted setup for that version). A
309	// refused submission leaves no job behind.
310	//
311	// A non-empty CompiledHash additionally binds the job to the pinned
312	// version's compiled artifact, matched as the exact string: a version with
313	// no compiled artifact yields ErrArtifactMissing and a hash that differs
314	// from that artifact's hash yields ErrArtifactMismatch. Artifacts of other
315	// names or versions never satisfy the binding. An empty CompiledHash leaves
316	// the job unbound and keeps the register-only behavior.
317	//
318	// Resubmitting the same id with the same request — including the same
319	// optional hash — returns the stored job; the same id with different content
320	// yields ErrConflict, reported before any artifact check of the new request.
321	// A stored job stays pinned to the version submitted, regardless of circuit
322	// versions added later.
323	func (s *Store) SubmitJob(job Job) (Job, error) {
324		if strings.TrimSpace(job.ID) == "" {
325			return Job{}, invalidf("job id must be non-empty and not only whitespace")
326		}
327		if strings.TrimSpace(job.Circuit) == "" {
328			return Job{}, invalidf("job %q must name a circuit", job.ID)
329		}
330		if job.Version <= 0 {
331			return Job{}, invalidf("job %q must pin a positive circuit version", job.ID)
332		}
333		if job.Attempt <= 0 {
334			return Job{}, invalidf("job %q attempt must be a positive integer", job.ID)
335		}
336		if job.Kind != "prove" {
337			return Job{}, StoreError{Kind: ErrUnsupportedKind.Kind,
338				Detail: "job " + job.ID + " has unsupported kind " + job.Kind + "; only \"prove\" jobs are accepted"}
339		}
340	
341		var result Job
342		err := s.withLock(func() (bool, error) {
343			if existing := findJob(s.data.Jobs, job.ID); existing != nil {
344				if !sameJobRequest(*existing, job) {
345					return false, conflictf("job %q already exists with a different request", job.ID)
346				}
347				result = jobFromPersist(*existing)
348				return false, nil
349			}
350			circuit := findCircuit(s.data.Circuits, job.Circuit, job.Version)
351			if circuit == nil {
352				return false, notFoundf("job %q references unknown circuit %q version %d", job.ID, job.Circuit, job.Version)
353			}
354			if !circuit.Frozen {
355				return false, notFrozenf("job %q references circuit %q version %d which is not frozen", job.ID, job.Circuit, job.Version)
356			}
357			if findSetup(s.data.Setups, job.Circuit, job.Version) == nil {
358				return false, setupMissingf("job %q references frozen circuit %q version %d which has no recorded trusted setup",
359					job.ID, job.Circuit, job.Version)
360			}
361			if job.CompiledHash != "" {
362				artifact := findArtifact(s.data.Artifacts, job.Circuit, job.Version)
363				if artifact == nil {
364					return false, artifactMissingf("job %q references circuit %q version %d which has no compiled artifact",
365						job.ID, job.Circuit, job.Version)
366				}
367				if artifact.Hash != job.CompiledHash {
368					return false, artifactMismatchf("artifact hash %q does not belong to circuit %q version %d (bound hash %q)",
369						job.CompiledHash, job.Circuit, job.Version, artifact.Hash)
370				}
371			}
372			record := persistJob{
373				ID: job.ID, Circuit: job.Circuit, Version: job.Version,
374				Kind: job.Kind, Attempt: job.Attempt, Artifact: job.Artifact,
375				CompiledHash: job.CompiledHash,
376			}
377			s.data.Jobs = append(s.data.Jobs, record)
378			result = jobFromPersist(record)
379			return true, nil
380		})
381		return result, err
382	}
383	
384	// GetCircuit returns one circuit version, sorted-field populated exactly as
385	// stored. Unknown versions yield ErrNotFound.
386	func (s *Store) GetCircuit(name string, version int) (Circuit, error) {
387		if err := validateCircuitKey(name, version); err != nil {
388			return Circuit{}, err
389		}
390		var result Circuit
391		err := s.withLockRead(func() error {
392			existing := findCircuit(s.data.Circuits, name, version)
393			if existing == nil {
394				return notFoundf("circuit %q version %d does not exist", name, version)
395			}
396			result = circuitFromPersist(*existing)
397			return nil
398		})
399		return result, err
400	}
401	
402	// ListCircuits returns all stored circuit versions ordered by circuit name
403	// (lexicographically) and then by ascending version number.
404	func (s *Store) ListCircuits() ([]Circuit, error) {
405		var result []Circuit
406		err := s.withLockRead(func() error {
407			ordered := append([]persistCircuit(nil), s.data.Circuits...)
408			sort.Slice(ordered, func(i, j int) bool {
409				if ordered[i].Name != ordered[j].Name {
410					return ordered[i].Name < ordered[j].Name
411				}
412				return ordered[i].Version < ordered[j].Version
413			})
414			result = make([]Circuit, len(ordered))
415			for i, c := range ordered {
416				result[i] = circuitFromPersist(c)
417			}
418			return nil
419		})
420		return result, err
421	}
422	
423	// GetSetup reports whether a trusted setup is registered for the named
424	// frozen version. A missing record yields ErrNotFound.
425	func (s *Store) GetSetup(name string, version int) (Setup, bool, error) {
426		if err := validateCircuitKey(name, version); err != nil {
427			return Setup{}, false, err
428		}
429		var result Setup
430		found := false
431		err := s.withLockRead(func() error {
432			existing := findSetup(s.data.Setups, name, version)
433			if existing == nil {
434				return nil
435			}
436			result = setupFromPersist(*existing)
437			found = true
438			return nil
439		})
440		return result, found, err
441	}
442	
443	// GetJob returns one stored job by id. Unknown ids yield ErrNotFound.
444	func (s *Store) GetJob(id string) (Job, error) {
445		if strings.TrimSpace(id) == "" {
446			return Job{}, invalidf("job id must be non-empty and not only whitespace")
447		}
448		var result Job
449		err := s.withLockRead(func() error {
450			existing := findJob(s.data.Jobs, id)
451			if existing == nil {
452				return notFoundf("job %q does not exist", id)
453			}
454			result = jobFromPersist(*existing)
455			return nil
456		})
457		return result, err
458	}
459	
460	// ListJobs returns all accepted jobs ordered by job id lexicographically.
461	func (s *Store) ListJobs() ([]Job, error) {
462		var result []Job
463		err := s.withLockRead(func() error {
464			ordered := append([]persistJob(nil), s.data.Jobs...)
465			sort.Slice(ordered, func(i, j int) bool { return ordered[i].ID < ordered[j].ID })
466			result = make([]Job, len(ordered))
467			for i, j := range ordered {
468				result[i] = jobFromPersist(j)
469			}
470			return nil
471		})
472		return result, err
473	}
474	
475	// --- validation helpers ---------------------------------------------------
476	
477	func validateCircuitKey(name string, version int) error {
478		if strings.TrimSpace(name) == "" {
479			return invalidf("circuit name must be non-empty and not only whitespace")
480		}
481		if version <= 0 {
482			return invalidf("circuit %q version must be a positive integer, got %d", name, version)
483		}
484		return nil
485	}
486	
487	func validateCounts(constraints, publicInputs, privateInputs int) error {
488		if constraints <= 0 {
489			return invalidf("constraints must be greater than zero, got %d", constraints)
490		}
491		if publicInputs < 0 {
492			return invalidf("public input count must not be negative, got %d", publicInputs)
493		}
494		if privateInputs < 0 {
495			return invalidf("private input count must not be negative, got %d", privateInputs)
496		}
497		return nil
498	}
499	
500	// --- lookup / mapping helpers --------------------------------------------
501	
502	func findCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
503		for i := range cs {
504			if cs[i].Name == name && cs[i].Version == version {
505				return &cs[i]
506			}
507		}
508		return nil
509	}
510	
511	func findSetup(ps []persistSetup, name string, version int) *persistSetup {
512		for i := range ps {
513			if ps[i].Name == name && ps[i].Version == version {
514				return &ps[i]
515			}
516		}
517		return nil
518	}
519	
520	func findJob(js []persistJob, id string) *persistJob {
521		for i := range js {
522			if js[i].ID == id {
523				return &js[i]
524			}
525		}
526		return nil
527	}
528	
529	func sameJobRequest(stored persistJob, request Job) bool {
530		return stored.Circuit == request.Circuit &&
531			stored.Version == request.Version &&
532			stored.Kind == request.Kind &&
533			stored.Attempt == request.Attempt &&
534			stored.CompiledHash == request.CompiledHash
535	}
536	
537	func circuitFromPersist(c persistCircuit) Circuit {
538		return Circuit{
539			Name: c.Name, Version: c.Version,
540			Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
541			Frozen: c.Frozen, Description: c.Description,
542		}
543	}
544	
545	// circuitCopyMatches reports whether target is the same draft content that a
546	// copy of source would create: same description, same three counts and a
547	// semantically equal constraint definition. Definition equality follows the
548	// existing normalization semantics (terms merged per wire, coefficients
549	// reduced modulo p, zeros dropped, wires sorted ascending); a missing
550	// definition differs from a present one.
551	func circuitCopyMatches(source, target persistCircuit) bool {
552		if source.Description != target.Description {
553			return false
554		}
555		if source.Constraints != target.Constraints ||
556			source.PublicInputs != target.PublicInputs ||
557			source.PrivateInputs != target.PrivateInputs {
558			return false
559		}
560		return definitionsEqual(source.Definition, target.Definition, source.PublicInputs, source.PrivateInputs)
561	}
562	
563	// definitionsEqual compares two stored definitions for semantic equality.
564	// Both nil is equal; one nil and the other not is different. When both are
565	// present they are parsed through the existing normalization pipeline and
566	// compared by modulus, constraint count and each side's wire/coefficient
567	// pairs. The public/private layout is the source's; the caller has already
568	// confirmed the counts match.
569	func definitionsEqual(d1, d2 *persistDefinition, public, private int) bool {
570		if d1 == nil && d2 == nil {
571			return true
572		}
573		if d1 == nil || d2 == nil {
574			return false
575		}
576		p1, err := definitionFromPersist(*d1, public, private)
577		if err != nil {
578			return false
579		}
580		p2, err := definitionFromPersist(*d2, public, private)
581		if err != nil {
582			return false
583		}
584		if p1.modulus != p2.modulus || len(p1.constraints) != len(p2.constraints) {
585			return false
586		}
587		for i := range p1.constraints {
588			if !canonicalTermsEqual(p1.constraints[i].a, p2.constraints[i].a) ||
589				!canonicalTermsEqual(p1.constraints[i].b, p2.constraints[i].b) ||
590				!canonicalTermsEqual(p1.constraints[i].c, p2.constraints[i].c) {
591				return false
592			}
593		}
594		return true
595	}
596	
597	// canonicalTermsEqual reports whether two normalized term slices are
598	// identical wire-by-wire and coefficient-by-coefficient.
599	func canonicalTermsEqual(t1, t2 []parsedTerm) bool {
600		if len(t1) != len(t2) {
601			return false
602		}
603		for i := range t1 {
604			if t1[i].wire != t2[i].wire || t1[i].value != t2[i].value {
605				return false
606			}
607		}
608		return true
609	}
610	
611	func setupFromPersist(p persistSetup) Setup {
612		return Setup{Name: p.Name, Version: p.Version}
613	}
614	
615	func jobFromPersist(j persistJob) Job {
616		return Job{
617			ID: j.ID, Circuit: j.Circuit, Version: j.Version,
618			Kind: j.Kind, Attempt: j.Attempt, Artifact: j.Artifact,
619			CompiledHash: j.CompiledHash,
620		}
621	}
622

