1	// Package zkcircuit implements circuit versioning and proving job orchestration.
2	package zkcircuit
3	
4	import "sort"
5	
6	// Circuit is one versioned arithmetic circuit.
7	type Circuit struct {
8		Name          string `json:"name"`
9		Version       int    `json:"version"`
10		Constraints   int    `json:"constraints"`
11		PublicInputs  int    `json:"public_inputs"`
