216	func countSetups(t *testing.T, s *Store) int {
217		t.Helper()
218		// No exported setup-list API; count through repeated job eligibility is
219		// indirect, so inspect the committed envelope directly.
220		s.mu.Lock()
221		defer s.mu.Unlock()
222		if err := lockShared(s.lock); err != nil {
223			t.Fatal(err)
224		}
225		defer unlockLock(s.lock)
226		if err := s.loadLocked(); err != nil {
227			t.Fatal(err)
228		}
229		return len(s.data.Setups)
230	}
