echo "=== Mutation 1 (normalized hash compare) ==="
go test ./zkcircuit/ -run 'TestSubmitJobHashMatchesExactly' 2>&1 | tail -3
cp /tmp/operations.go.bak zkcircuit/operations.go

# Mutation 2: 冲突检查挪到产物校验之后（用临时改写：先电路/产物校验块，再 existing 块）
python3 - <<'EOF'
import re
src = open('zkcircuit/operations.go').read()
old = '''	var result Job
	err := s.withLock(func() (bool, error) {
		if existing := findJob(s.data.Jobs, job.ID); existing != nil {
			if !sameJobRequest(*existing, job) {
				return false, conflictf("job %q already exists with a different request", job.ID)
			}
			result = jobFromPersist(*existing)
			return false, nil
		}
'''
new = '''	var result Job
	err := s.withLock(func() (bool, error) {
		circuit0 := findCircuit(s.data.Circuits, job.Circuit, job.Version)
		if job.CompiledHash != "" && circuit0 != nil {
			if a := findArtifact(s.data.Artifacts, job.Circuit, job.Version); a == nil {
				return false, artifactMissingf("x")
			} else if a.Hash != job.CompiledHash {
				return false, artifactMismatchf("x")
			}
		}
		if existing := findJob(s.data.Jobs, job.ID); existing != nil {
			if !sameJobRequest(*existing, job) {
				return false, conflictf("job %q already exists with a different request", job.ID)
			}
			result = jobFromPersist(*existing)
			return false, nil
		}
'''
assert old in src
open('zkcircuit/operations.go','w').write(src.replace(old,new))
EOF
echo "=== Mutation 2 (artifact check before id conflict) ==="
go test ./zkcircuit/ -run 'TestSubmitJobBindingConflictPreservesStoredJob' 2>&1 | tail -3
cp /tmp/operations.go.bak zkcircuit/operations.go

# Mutation 3: 空哈希时自动绑定已编译产物
python3 - <<'EOF'
src = open('zkcircuit/operations.go').read()
old = '''		record := persistJob{
			ID: job.ID, Circuit: job.Circuit, Version: job.Version,
			Kind: job.Kind, Attempt: job.Attempt, Artifact: job.Artifact,
			CompiledHash: job.CompiledHash,
		}'''
new = '''		boundHash := job.CompiledHash
		if boundHash == "" {
			if a := findArtifact(s.data.Artifacts, job.Circuit, job.Version); a != nil {
				boundHash = a.Hash
			}
		}
		record := persistJob{
			ID: job.ID, Circuit: job.Circuit, Version: job.Version,
			Kind: job.Kind, Attempt: job.Attempt, Artifact: job.Artifact,
			CompiledHash: boundHash,
		}'''
assert old in src
open('zkcircuit/operations.go','w').write(src.replace(old,new))
EOF
echo "=== Mutation 3 (auto-bind empty hash) ==="
go test ./zkcircuit/ -run 'TestEmptyHashLeavesJobUnbound' 2>&1 | tail -3
cp /tmp/operations.go.bak zkcircuit/operations.go

